// Generated by scripts/build-app-guide.mjs from docs/guide. Do not edit: change the guide and run `npm run guide`.
import type { AppGuideTopic } from "./app-guide.js";

export const APP_GUIDE_TOPICS: ReadonlyArray<AppGuideTopic> = [
  {"id":"overview","title":"Where things are","summary":"Map of every settings panel and every page of a Wisp's own settings, with what each one configures. Start here for \"where do I configure X\".","body":"# Where things are\n\nWisp has two kinds of settings.\n\n## Application settings\n\nOpen them from your name at the bottom of the sidebar (**User settings**).\nThey apply to the whole app and every Wisp.\n\n| Panel | What it holds |\n| --- | --- |\n| [General](wisp://settings/general) | Your profile (name, about you, response preferences), theme, Wisp colors, launch at login, timezone, auto-review of file changes, integration blocks |\n| [Connections](wisp://settings/connections) | Where your Wisps run: this computer or a Wisp server |\n| [Remote access](wisp://settings/remote-access) | Use this computer's Wisps from your phone or another device |\n| [AI Model](wisp://settings/model) | Default provider and model, provider API keys, output token limit, image model |\n| [Voice input](wisp://settings/voice) | Transcription provider, model, language, microphone, send automatically |\n| [Plugins](wisp://settings/plugins) | Web search and page reading (Brave Search, Firecrawl, Tavily, Exa), Linear, and which Wisps use them |\n| [MCP servers](wisp://settings/mcp) | Outside tools connected over MCP, and which Wisps use them |\n| [Jobs](wisp://settings/jobs) | Every scheduled job of every Wisp: pause, resume, run now, delete |\n| [Token usage](wisp://settings/usage) | Tokens and estimated cost per Wisp over time |\n| [Storage](wisp://settings/storage) | Space used by each workspace, cleanup, archives of deleted Wisps |\n| [Notifications](wisp://settings/notifications) | Sounds for finished replies, approvals and errors |\n| [Shortcuts](wisp://settings/shortcuts) | Keyboard shortcuts |\n| [About](wisp://settings/about) | Version, updates, release notes |\n\n## A Wisp's settings\n\nOpen them with the gear in the conversation header (**Open Wisp settings**).\nThey apply only to that Wisp. On the desktop they are tabs: **General**,\n**Model**, **Access**, **Usage**, with **Context & memory**, **Skills**,\n**Workspace**, **Commands** and **Jobs** as sections inside **General**. On a\nphone they are pages listed on the Wisp's profile.\n\n| Page | What it holds |\n| --- | --- |\n| [Profile](wisp://wisp/profile) | Appearance, name, role, soul, notifications for this Wisp; share as template; delete |\n| [Model](wisp://wisp/model) | The model this Wisp runs on, and its reasoning level |\n| [Access](wisp://wisp/access) | Which plugins and MCP servers this Wisp can use |\n| [Usage](wisp://wisp/usage) | This Wisp's session report: tokens, cost, tool calls |\n| [Context & memory](wisp://wisp/memory) | Context renewal, summaries, new topics, saved memory |\n| [Skills](wisp://wisp/skills) | Saved procedures this Wisp follows |\n| [Workspace](wisp://wisp/workspace) | This Wisp's private folder and its size |\n| [Commands](wisp://wisp/execution) | Running commands in a container, GitHub token, local network |\n| [Jobs](wisp://wisp/jobs) | This Wisp's scheduled jobs |"},
  {"id":"access","title":"Access and approvals","summary":"What Wisps can do without asking, approval cards, auto-review of file changes, always allowing or blocking, integration blocks, and reviewing what a Wisp can use.","body":"# Access and approvals\n\n## Approval cards\n\nSome actions need your approval: file changes (depending on auto-review),\nintegration calls that change something, MCP tool calls, saving a skill and\ncreating a job. The card shows what will happen; choose **Allow once** or\n**Deny**, or, where offered, an **Always allow** or **Always block** choice.\nPending approvals show in the conversation and the sidebar; on a phone they\nalso have their own tab.\n\n## File changes\n\n**Auto-review file changes** in [General](wisp://settings/general), under\n**Wisp**, has one **Allow / Ask / Block** choice for **Create files** and one\nfor **Modify files**. Turning auto-review off makes every file change ask.\n**Always allow** and **Always block** on a file approval card change the same\nchoices. Wisps only ever change files inside their own workspace.\n\n**Integration blocks**, in the same section, lists the blocks added from\napproval cards (such as **Block all integration calls**) and lets you remove\nthem.\n\n## What a Wisp can use\n\nA Wisp's [Access](wisp://wisp/access) page lists the plugins and MCP servers it\ncan use and its always-allowed MCP tools. Commands are set in its\n[Commands](wisp://wisp/execution) settings."},
  {"id":"commands","title":"Running commands","summary":"Letting a Wisp run shell commands and git in its own container (Docker or Podman), the container image, a GitHub token for private repositories, and local network access.","body":"# Running commands\n\nBy default Wisps cannot run commands. In the Wisp's\n[Commands](wisp://wisp/execution) settings, set **Run commands** to **In a\ncontainer**. It can also be chosen when creating the Wisp.\n\n- Commands run in the Wisp's own container, never directly on your computer.\n  It needs Docker or Podman on the computer that runs the Wisps. The container\n  sees only the Wisp's workspace.\n- **Image** chooses the container image; the default is **Wisp sandbox\n  (Debian)**. Changing it recreates the container.\n- **GitHub token** — a fine-grained token lets git in the container reach\n  your private repositories on github.com. It is stored encrypted, and the\n  Wisp can push whatever the token allows.\n- Commands reach the internet but not your local network, unless **Allow\n  local network** is on.\n\nCommands run without approval cards: the container is the boundary. Do not\nkeep secrets in a workspace."},
  {"id":"connections","title":"Connections and Wisp servers","summary":"Running Wisps on this computer or on a Wisp server, connecting over SSH or HTTPS, installing or updating the server from the app, and what is kept separately in each place.","body":"# Connections and Wisp servers\n\n[Connections](wisp://settings/connections) chooses where your Wisps run.\n\n- **This computer** — the default. Wisps run while the app is open.\n- **A Wisp server** — a Linux machine running the Wisp server, so Wisps keep\n  working (jobs, scheduled messages) with the app closed. Add it over **SSH**\n  (with your SSH keys and config) or by its **HTTPS address**, such as a\n  Tailscale Serve address. Over SSH, **Install the Wisp server** sets it up\n  for you, and **Install or update the server** updates it to the app's\n  version. The panel has a short **How to set up a Wisp server** guide.\n\nChoosing **Use** switches every Wisp, conversation, setting and key to that\nplace. Each place keeps its own; nothing is copied between them.\n\nOn a server, opening a Wisp's folder and MCP OAuth sign-in are not available\nfrom other computers. Files you attach are uploaded to it."},
  {"id":"conversations","title":"Conversations and the composer","summary":"Sending messages, attaching files, voice input, scheduling a message, queueing messages while the Wisp works, stopping a reply, starting a new topic, searching, and pinning, muting or marking conversations unread.","body":"# Conversations and the composer\n\n## The composer\n\n- **Attach files** — from the **+** button. Files are copied into the Wisp's\n  workspace `inbox/` folder; up to 20 per message, within the workspace size.\n- **Voice input** — the microphone button dictates a message. It needs a\n  transcription key; see the *Voice input* topic.\n- **Schedule send** — from the **+** menu, a long press or right click on the\n  send button, or **Ctrl+Shift+Enter** (**Cmd+Shift+Enter** on a Mac). The\n  message is sent at the chosen time.\n- **Queue message** — while the Wisp is working, a new message waits in a\n  queue and is sent when the current reply ends.\n- **Stop response** — stops the reply in progress.\n- **Start a new topic** — from the **+** menu: the next message starts\n  without the earlier context. See the *Context and memory* topic.\n\n## Approvals\n\nWhen a Wisp needs permission, for example to change a file or call an\nintegration, an approval card appears in the conversation and the sidebar\nshows **Waiting for your approval**. See the *Access and approvals* topic.\n\n## The conversation list\n\nRight-click a conversation to pin it, mute its notifications, or mark it as\nread or unread. **Ctrl+K** (**Cmd+K**) opens the search dialog, which searches\nWisps, circles and messages. **Ctrl+B** (**Cmd+B**) collapses the sidebar on\nthe desktop.\n\nCircles, conversations with several Wisps, are not enabled yet."},
  {"id":"getting-started","title":"Getting started and creating Wisps","summary":"First-run setup, creating a Wisp (appearance, soul, model, workspace, templates), sharing a Wisp as a template, and deleting one.","body":"# Getting started and creating Wisps\n\n## First run\n\nBefore the workspace opens, Wisp asks only for what is missing: your\npreferred name, a default model, and an API key for that model's provider.\nA new installation also asks **Where should your Wisps run?**: on this\ncomputer (recommended) or on a Wisp server (see the *Connections and Wisp\nservers* topic). Change these later in [General](wisp://settings/general),\n[AI Model](wisp://settings/model) and [Connections](wisp://settings/connections).\n\n## Creating a Wisp\n\nSelect **Create Wisp** in the sidebar. The dialog has sections for:\n\n- **Appearance and name** — its look, color, name and an optional role.\n- **Soul and behavior** — the soul: who the Wisp is and how it behaves,\n  written in Markdown. **Start from a template** offers ready-made souls.\n- **Model** — keep **Use global model** or choose a provider and model for\n  this Wisp. The model is chosen here and cannot be changed later for now.\n- **Workspace and commands** — the size of its private folder, and whether it\n  can run commands in a container.\n\n**Import template** fills the dialog from a template someone copied with\n**Share as template**.\n\nA Wisp needs a usable model: the global default with a saved provider key, or\nits own model whose provider has a saved key.\n\n## Sharing and deleting\n\nIn the Wisp's [Profile](wisp://wisp/profile) (on the desktop, the bottom of\nthe **General** tab), **Share as template** copies its soul and model so it\ncan be pasted into **Import template**. **Delete Wisp** permanently deletes\nit with its history and settings; its workspace files are kept as an archive\nin [Storage](wisp://settings/storage) until you delete them there.\n\nEach Wisp has its own conversation. Your profile in\n[General](wisp://settings/general) (preferred name, about you, response\npreferences) is shared with every Wisp."},
  {"id":"jobs","title":"Jobs and scheduled messages","summary":"Tasks a Wisp runs on a schedule in the background (once, daily, weekly, monthly), how to create, approve, pause, run now or delete them, and how they differ from scheduled messages.","body":"# Jobs and scheduled messages\n\n## Jobs\n\nA job is a task a Wisp runs on its own on a schedule, such as \"every morning,\nlook for new job openings and send me what you find\". Each run works in the\nbackground and only its result arrives in the conversation; a run with\nnothing to report can stay silent.\n\n- **Create or change** — ask the Wisp in its conversation; there is no form.\n  It proposes the title, schedule, instructions, skills and tools, and you\n  approve them in a card. Changing the instructions or adding tools asks again.\n- **Schedules** — once, daily, weekly on chosen days, or monthly, at a time\n  in your timezone, with an optional end. A job runs at most once a day.\n- **Manage** — [Jobs](wisp://settings/jobs) lists every Wisp's jobs and their\n  runs, with **Run now**, **Pause**, **Resume** and delete. A Wisp's\n  [Jobs](wisp://wisp/jobs) settings show its own jobs.\n\nRuns have no one to ask, so they can use only the tools approved with the\njob. A job that fails several times in a row is paused.\n\n## Scheduled messages\n\nTo send one message later, use **Schedule send** in the composer (see the\n*Conversations and the composer* topic). Unlike a job, it is a normal message\nin the conversation, sent at the chosen time."},
  {"id":"mcp-servers","title":"MCP servers","summary":"Connecting remote MCP servers (HTTPS, with no authentication, a header or OAuth), testing and refreshing their tools, giving Wisps access, and always allowing a tool.","body":"# MCP servers\n\n[MCP servers](wisp://settings/mcp) connects outside tools that speak the\nModel Context Protocol.\n\n## Add a server\n\nAdd the server's HTTPS address and choose its authentication: **None**, an\n**Authentication header** (stored encrypted), or **OAuth** (sign in in the\nbrowser). Wisp discovers the server's tools when it is saved;\n**Test connection** checks it and **Refresh tools** discovers them again.\nOnly remote servers over HTTPS are supported, not local (stdio) servers.\nOAuth sign-in needs the desktop app on the computer that runs the Wisps.\n\n## Give a Wisp access\n\nAdding a server grants nothing. Grant it in each Wisp's\n[Access](wisp://wisp/access) page, or for every Wisp at once in the server's\n**Wisp access** section. Every MCP tool call asks for approval; the approval\ncard's **Always allow this tool** skips the question for that tool and Wisp\nuntil the tool changes. The Wisp's Access page lists always-allowed tools so\nyou can make them ask again.\n\nSome models accept a limited number of tools. If a reply fails because of too\nmany tools, remove access to servers the Wisp does not need."},
  {"id":"memory","title":"Context and memory","summary":"How a Wisp keeps context, automatic context renewal, summarizing, starting a new topic, saved memory that survives every topic, and finding earlier messages.","body":"# Context and memory\n\nOpen the Wisp's [Context & memory](wisp://wisp/memory) settings.\n\n## Context renewal\n\nBy default, the next message after 24 hours of inactivity starts a new topic,\nbut only when the active context is at least 12,000 tokens. **Renew context**\ncan follow inactivity or a daily hour (in your timezone from\n[General](wisp://settings/general)), and **On renewal** either starts a new\ntopic or **Summarize and continue**. A summary keeps goals, decisions and\npending work but costs a summarization request; a new topic sends the fewest\ntokens. The thresholds are adjustable.\n\n## Summaries and new topics\n\n**Summarize context** condenses the conversation and keeps its recent part;\n**View continuity summary** shows the current summary. **Start new topic**\nclears the active context while keeping every message on screen and the\nWisp's identity, model and saved memory. A marker in the conversation shows\neach boundary.\n\nEither way the Wisp can still find earlier messages by searching its history.\n\n## Saved memory\n\n**Saved memory** is text you write: preferences and facts to keep across\ntopics. It is sent with every request and survives new topics and restarts.\nWisps never add to it on their own."},
  {"id":"models","title":"AI models and provider keys","summary":"Choosing the default model and provider, adding or removing API keys, a Wisp's own model and reasoning level, the output token limit, and the image model for Wisps whose model cannot see images.","body":"# AI models and provider keys\n\n## Default model and keys\n\n[AI Model](wisp://settings/model) holds the provider and model every Wisp\nuses unless it has its own, the **Maximum output tokens**, the **Reasoning**\nlevel (how much the model thinks before it answers; higher levels cost more\nand reply slower), and the API key of each provider. Only API keys are supported; they are stored encrypted and are\nshared by every Wisp using that provider. Removing a key stops the Wisps that\nuse that provider until a key is saved again.\n\nThe model list comes from the runtime's catalog, refreshed in the background;\na failed refresh is shown in this panel.\n\n## A Wisp's own model\n\nA Wisp's model is chosen when it is created (see *Getting started*).\nIts [Model](wisp://wisp/model) page shows the model it runs on and lets you\npick its reasoning level when the model supports one. The conversation header\nshows the model in use. If its model or key becomes unusable, the Wisp asks\nfor configuration rather than switching to another provider.\n\n## Images and models that cannot see them\n\nSome models cannot read images. **Auxiliary models → Image understanding** in\n[AI Model](wisp://settings/model) picks a second model that reads images and\nscanned PDF pages for those Wisps and gives them a text description. It is\n**Off** by default and lists only image-capable models whose provider has a\nsaved key. The composer says when a Wisp's model cannot see images.\n\n## When sending is disabled\n\nIf the composer says to choose a provider and model, select **Configure AI\nmodel** or open [AI Model](wisp://settings/model). Your draft is kept."},
  {"id":"plugins","title":"Web search and plugins","summary":"Giving Wisps web search and page reading, connecting Brave Search, Firecrawl, Tavily, Exa or Linear, default web providers, and granting a plugin to a Wisp.","body":"# Web search and plugins\n\nWisps have no web access until you connect a plugin and give a Wisp access.\n\n## Connect a plugin\n\nOpen [Plugins](wisp://settings/plugins), choose a plugin under **Available**,\npaste its API key (each form links to where to get one) and select\n**Connect**. The key is tested before it is saved. The plugins are:\n\n- **Brave Search** — web search.\n- **Firecrawl**, **Tavily**, **Exa** — web search and reading pages.\n- **Linear** — read issues, or also create and update them.\n\nA connected plugin's page has **Test connection**, **Replace key**,\n**Remove connection** and an **Enabled** switch. With several web providers\nconnected, **Default web providers** chooses which one is suggested first.\n\n## Give a Wisp access\n\nConnecting grants nothing by itself. In the Wisp's\n[Access](wisp://wisp/access) page, under **Web**, choose a provider for\n**Search the web** and **Read web pages**; under **Apps**, choose **Read only**\nor **Read and write** for Linear; then **Save access**. A plugin's page in\n[Plugins](wisp://settings/plugins) offers the same choices for every Wisp at\nonce. New tools are available from the Wisp's next message.\n\nCreating or changing Linear issues always asks for approval first."},
  {"id":"preferences","title":"Notifications, appearance and shortcuts","summary":"Notification sounds and volume, muting a Wisp or the open conversation, theme and Wisp colors, timezone, launch at login, and keyboard shortcuts.","body":"# Notifications, appearance and shortcuts\n\n## Notifications\n\n[Notifications](wisp://settings/notifications) turns **Notification sounds**\non or off, sets the volume, and chooses which events play a sound: **Response\ncompleted**, **Approval needed** and **Execution error**. **Mute the open\nconversation** silences the conversation on screen. Each Wisp also has its own\n**Notifications** switch in its [Profile](wisp://wisp/profile), and a\nconversation can be muted from the conversation list. Only sounds are\navailable for now, not system notifications.\n\n## Appearance and system\n\n[General](wisp://settings/general) has the theme (system, light or dark),\n**Wisp colors** (off keeps a neutral look), **Launch at login** (Linux\nreleases only), and the timezone used for every date in the app and by Wisps.\n\n## Shortcuts\n\n[Shortcuts](wisp://settings/shortcuts) lists the built-in shortcuts and lets\nyou change the one for voice input. Built in: **Ctrl+K** search, **Ctrl+B**\ncollapse the sidebar, **Ctrl+Shift+Enter** schedule a message (**Cmd** instead\nof **Ctrl** on a Mac)."},
  {"id":"remote-access","title":"Remote access and using Wisp on a phone","summary":"Using this computer's Wisps from a phone or browser, turning on remote access with Tailscale, pairing a device with a QR code, revoking devices, and installing the browser app on a phone.","body":"# Remote access and using Wisp on a phone\n\n[Remote access](wisp://settings/remote-access) lets your phone or another\ndevice use the Wisps on this computer. (To make this app use Wisps on a\nserver instead, see *Connections and Wisp servers*.)\n\n1. Install Tailscale on this computer and on the phone, signed in to the same\n   tailnet. With Tailscale ready, turning remote access on takes one click;\n   otherwise the panel says what to fix, or **Set it up by hand** walks\n   through it.\n2. Under **Pair a device**, select **Show QR code** and scan it with the\n   phone. The code works once and lasts 10 minutes.\n3. On the phone, add the page to the home screen (**Share → Add to Home\n   Screen** in Safari, **Install app** in Chrome) to open it like an app.\n\nWhile remote access is on, the app keeps running in the tray with its windows\nclosed. **Paired devices** lists the devices; **Revoke** signs one out.\nA Wisp server can be opened in a browser the same way, after pairing with a\ncode from `wispctl pair` on the server."},
  {"id":"skills","title":"Skills","summary":"Saving a workflow as a skill, importing a SKILL.md file, how Wisps use skills, and managing them.","body":"# Skills\n\nA skill is a reusable procedure a Wisp follows when a request matches it.\nEach Wisp has its own skills.\n\n- **Save a workflow** — ask the Wisp to turn something you did together into\n  a skill. It drafts general instructions, and an approval card shows exactly\n  what will be saved.\n- **Import a file** — attach a `SKILL.md` and ask the Wisp to save it; it is\n  saved as written after your approval. Skills follow the Agent Skills format:\n  a `SKILL.md` with `name` and `description` front matter.\n- **Manage** — the Wisp's [Skills](wisp://wisp/skills) settings list its\n  skills, show their instructions, import a file, delete one, open the folder\n  that holds them, and reload them after editing by hand.\n\nThe Wisp sees the name and description of each skill and loads the full\ninstructions when one applies. Skills never grant tools or permissions.\nJobs can load skills in every run (see the *Jobs* topic)."},
  {"id":"updates","title":"Updates and version","summary":"Checking for updates, installing them on Linux and macOS, the app version and release notes.","body":"# Updates and version\n\n[About](wisp://settings/about) shows the version and checks for updates when\nyou ask; nothing downloads on its own.\n\n- **Linux** (AppImage and `.deb`) downloads and installs updates in place; the\n  `.deb` asks for the administrator password.\n- **macOS** builds cannot install updates themselves: About shows the new\n  version and opens the releases page to download it.\n\nA Wisp server shows its version in [Connections](wisp://settings/connections)\nand warns when it differs from the app's."},
  {"id":"usage","title":"Token usage and costs","summary":"How many tokens each Wisp used, estimated costs, the token usage dashboard and a Wisp's session report.","body":"# Token usage and costs\n\n- [Token usage](wisp://settings/usage) shows totals and a breakdown by Wisp\n  for the last 7 days, the last 30 days or all history.\n- A Wisp's [Usage](wisp://wisp/usage) page shows its session report: models,\n  tokens, tool calls, summaries and retries.\n\nCosts in US dollars are estimates from current public model prices, not\ninvoices; a cost stays unknown when no price is available. Summaries and the\nimage model count in the totals."},
  {"id":"voice","title":"Voice input","summary":"Dictating messages, choosing the transcription provider (Groq, OpenAI, Mistral), model, language and microphone, and sending automatically after transcription.","body":"# Voice input\n\n[Voice input](wisp://settings/voice) sets up dictation:\n\n- **Transcription** — the provider (Groq, OpenAI or Mistral), the model, and\n  the language you speak, which improves accuracy.\n- **Credential** — the provider's API key, the same key\n  [AI Model](wisp://settings/model) uses for that provider.\n- **Recording** — the microphone, and **Send automatically**: on, the message\n  is sent as soon as it is transcribed; off, the text waits in the composer.\n\nThen use the microphone button in the composer, or the shortcut set in\n[Shortcuts](wisp://settings/shortcuts). **Esc** cancels a recording. In a\nbrowser, voice input needs an HTTPS address."},
  {"id":"workspace","title":"Workspaces and storage","summary":"A Wisp's private folder, opening it, where attached files go, workspace size, freeing space, the Storage panel, and archives of deleted Wisps.","body":"# Workspaces and storage\n\nEach Wisp has a private folder, its workspace. Its file tools work only\nthere, and attached files land in its `inbox/` folder.\n\n## A Wisp's workspace\n\nThe Wisp's [Workspace](wisp://wisp/workspace) settings show how much space it\nuses, open the folder (in the desktop app on the computer that runs the\nWisps), and choose its **Size**. A workspace above its size keeps its files,\nbut no new files fit until you free space. **Inspect and clean up** opens it\nin Storage.\n\n## Storage\n\n[Storage](wisp://settings/storage) lists every workspace with its usage.\nOpen one to see which folders take the space, and remove files permanently\nafter a cleanup preview. **Archived** lists the files of deleted Wisps, which\nyou can delete permanently."},
];
